UPDATE community_service_requests SET revision=@Revision,service_id=@ServiceId,seller_id=@SellerId,user_id=@UserId,service_name=@ServiceName,description=@Description,preferred_at=@PreferredAt,price=@Price,currency=@Currency,price_unit=@PriceUnit,status=@Status,submission_id=@SubmissionId WHERE workspace_id=@WorkspaceId AND property_id=@PropertyId AND id=@Id AND revision=@Revision-1;
